def image(path):
    return "data:image/png;base64," + base64.b64encode(path.read_bytes()).decode("ascii")

font = ""
for candidate in (root / "neodgm.ttf", root / "neodgm(2).ttf"):
    if candidate.exists():
        font = base64.b64encode(candidate.read_bytes()).decode("ascii")
        break

st.markdown("""<style>html,body,.stApp,[data-testid="stAppViewContainer"],[data-testid="stMain"]{background:#02050a!important}header,footer,[data-testid="stSidebar"],[data-testid="stSidebarCollapsedControl"]{display:none!important}.block-container,[data-testid="stMainBlockContainer"]{padding:0!important;max-width:100vw!important;width:100%!important}iframe{display:block!important;border:0!important;width:100%!important}</style>""", unsafe_allow_html=True)
